raw_response:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "2 <= n <= 50000",
      "description": "The number of cities n is between 2 and 50000, inclusive."
    },
    {
      "id": "P2",
      "expression": "1 <= r1 != r2 <= n",
      "description": "The old and new capital indices r1 and r2 are different and within the range of city indices."
    },
    {
      "id": "P3",
      "expression": "len(old_representation) == n - 1",
      "description": "The old representation list contains n - 1 elements, one for each non-capital city."
    },
    {
      "id": "P4",
      "expression": "all(1 <= pi <= n for pi in old_representation)",
      "description": "Each element in the old representation list is a valid city index within the range of city indices."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(new_representation) == n - 1",
      "description": "The new representation list contains n - 1 elements, one for each non-capital city."
    },
    {
      "id": "Q2",
      "expression": "all(1 <= ni <= n for ni in new_representation)",
      "description": "Each element in the new representation list is a valid city index within the range of city indices."
    },
    {
      "id": "Q3",
      "expression": "all(new_representation[i] != new_representation[j] for i in range(n - 1) for j in range(i + 1, n - 1))",
      "description": "Each city in the new representation list is a unique index and is different from the new capital index r2."
    },
    {
      "id": "Q4",
      "expression": "all(new_representation[i] == r2 or new_representation[i] == pi for i in range(n - 1))",
      "description": "For each city i, the new representation of the road map contains the index of the last city on the way from the new capital to city i."
    }
  ],
  "invariants": []
}
